export function solve(operations: any[]): any {
  const subscriptions = new Map<string, Set<string>>();
  const out: any[] = [];
  for (const op of operations) {
    if (op.kind === "on") {
      if (!subscriptions.has(op.event)) subscriptions.set(op.event, new Set());
      subscriptions.get(op.event)!.add(op.id);
    } else if (op.kind === "off") subscriptions.get(op.event)?.delete(op.id);
    else for (const id of subscriptions.get(op.event) ?? []) out.push({ id, value: op.value });
  }
  return out;
}
